        "faqs": [
            {
                "question": "How much does website design and development cost?",
                "answer": "Depending on the level of customisation, the level of intricacy, and the person you employ, it may run anywhere from $300 to more than $100,000."
            },
            {
                "question": "How much does custom web design and development cost?",
                "answer": "Custom solutions typically begin at around $3,000 and may go up to more than $50,000, depending on the features and requirements of the organization."
            },
            {
                "question": "How much does it cost to pay someone to design your website?",
                "answer": "Freelancers may charge between $20 and $150 per hour, whereas agencies may charge between $75 and $250 per hour."
            },
            {
                "question": "How much should I pay to design a website?",
                "answer": "The majority of small companies spend between $2,000 and $10,000 on a website that is both professional and useful."
            }
        ],
